class TTLCache:
    def __init__(self, ttl, clock):
        if ttl < 0:
            raise ValueError("ttl must be nonnegative")
        self.ttl = ttl
        self._clock = clock
        self._items = {}

    def set(self, key, value):
        self._items[key] = (value, self._clock() + self.ttl)

    def get(self, key, default=None):
        if key not in self._items:
            return default
        value, expires = self._items[key]
        if self._clock() > expires:
            del self._items[key]
            return default
        return value
